# XXX: DEPRECATED
# TODO: Remove this

illegal_filename_characters = '\\:/*?"<>|'
illegal_path_characters = '/*?"<>|'


def generate_run_cmd(path, user_profile=None, proxy_port=None, auto_proxy=None,
                     auto_disconnect=None):
    """Generate a Windows shell command that runs TMA test application.

    The generated command follows a spec taken from TMAApplication
    documentation. A CRLF sequence ('\r\n') is added at the end:

    "<path>" [/u "<user_profile>"] [/p <proxy_port>] [/c (y|n)] [/a (y|n)]\r\n

    :path: A path to executable file (image) of TMAApplication. This cannot
    contain any of the characters disallowed in Windows paths,
    namely /*?"<>| . Also, the given string cannot be empty. If an illegal
    character is found in the path, a ValueError will be raised.
    :user_profile: user profile to open upon running the application. If set to
    None, the /u option will be ommitted. This should not contain any quotation
    characters.
    :proxy_port: Proxy port that will be inputed into /p option. If set to
    None, the option will be ommitted. Otherwise must be an integer from a
    range 0 < proxy_port < 65536. If it exceeds this range, a ValueError is
    raised. If given value is not a None and is not an int, a TypeError is
    raised.
    :auto_proxy: If given True, sets /c option to 'y', if given False,
    sets it to 'n'. If given None, the option is ommitted. This option makes
    TMA application create proxy port automatically when it starts.
    :auto_disconnect: If given True, sets /a option to 'y', if given False,
    sets it to 'n'. If given None, the option is ommitted. Setting this option
    to 'y', will make the TMA application automatically disconnect from TM500
    hardware if a connection to the proxy port is dropped.
    :returns: A CRLF terminated string containing a command that runs the TMA
    application.

    """
    _validate_path(path)
    user_profile = _generate_user_profile_option(user_profile)
    proxy_port = _generate_proxy_port(proxy_port)
    auto_proxy = _generate_auto_proxy(auto_proxy)
    auto_disconnect = _generate_auto_disconnect(auto_disconnect)
    command = '"{}"{}{}{}{}\r\n'.format(path, user_profile, proxy_port,
                                        auto_proxy, auto_disconnect)
    return command


def _validate_path(path):
    if not path:
        raise ValueError("path to TMA application cannot be an empty string.")
    if any(illegal in path for illegal in illegal_path_characters):
        raise ValueError("path contains illegal characters.")


def _generate_user_profile_option(user_profile):
    if user_profile is not None:
        _validate_user_profile(user_profile)
        return ' /u "{}"'.format(user_profile)
    return ''


def _validate_user_profile(user_profile):
    if not user_profile:
        raise ValueError("user_profile must be None or non-empty string.")
    if '"' in user_profile:
        exc_msg = "user_profile cannot contain any quotation marks."
        raise ValueError(exc_msg)


def _generate_proxy_port(proxy_port):
    if proxy_port is not None:
        _validate_proxy_port(proxy_port)
        return ' /p {}'.format(proxy_port)
    return ''


def _validate_proxy_port(proxy_port):
    if not isinstance(proxy_port, int):
        exc_msg = "invalid type of value given as proxy port: {}"
        exc_msg = exc_msg.format(type(proxy_port))
        raise TypeError(exc_msg)
    if not (0 < proxy_port < 65536):
        raise ValueError("proxy_port out of range.")


def _generate_auto_proxy(auto_proxy):
    if auto_proxy is not None:
        auto_proxy = ' /c ' + ('y' if auto_proxy else 'n')
        return auto_proxy
    return ''


def _generate_auto_disconnect(auto_disconnect):
    if auto_disconnect is not None:
        auto_disconnect = ' /a ' + ('y' if auto_disconnect else 'n')
        return auto_disconnect
    return ''


def generate_kill_cmd(imagename):
    r"""Generate a command that will kill the application with given imagename.

    :imagename: A non-empty string containing the imagename of the process,
    (for example TMA.exe). This cannot contain any of the characters disallowed
    in Windows filenames, namely /\:*?"<>| . Also, the given string cannot be
    empty. If an illegal character is found in the path, a ValueError will be
    raised.
    :returns: A CRLF terminated string containing a Windows shell command that
    when used will kill the application with the given imagename.

    """
    _validate_imagename(imagename)
    return _generate_task_cmd('TASKKILL', imagename)[:-2] + ' /F\r\n'


def generate_list_cmd(imagename):
    r"""Generate a command that will list running processes with given imagename

    :imagename: A non-empty string containing the imagename of the process,
    (for example TMA.exe). This cannot contain any of the characters disallowed
    in Windows filenames, namely /\:*?"<>| . Also, the given string cannot be
    empty. If an illegal character is found in the path, a ValueError will be
    raised.
    :returns: A CRLF terminated string containing a Windows shell command that
    when used will list running applications that have the given imagename.
    """
    _validate_imagename(imagename)
    return _generate_task_cmd('TASKLIST', imagename)


def _validate_imagename(imagename):
    if not imagename:
        raise ValueError('imagename cannot be empty.')
    if any(illegal in imagename for illegal in illegal_filename_characters):
        raise ValueError("imagename contains illegal characters.")


def _generate_task_cmd(base_cmd, imagename):
    return '{} /FI "IMAGENAME eq {}"\r\n'.format(base_cmd, imagename)
